def copy_users(apps, schema_editor):
    """Create a ThirdSideUser (same id) for every django User the app refers to.

    Same ids mean no foreign key has to be remapped, and the password hash is
    copied as is, so existing logins keep working. Roles come from Profile.
    """
    AuthUser = apps.get_model('auth', 'User')
    Profile = apps.get_model('third_side', 'Profile')
    NewUser = apps.get_model('third_side', 'ThirdSideUser')

    refs = set()
    for model, fields in (
        ('Profile', ['user_id']),
        ('Comment', ['user_id']),
        ('CommentLike', ['user_id']),
        ('Rating', ['user_id']),
        ('Report', ['reporter_id', 'reviewed_by_id']),
        ('Article', ['created_by_id']),
        ('Critic', ['user_id']),
    ):
        for field in fields:
            refs.update(
                apps.get_model('third_side', model)
                .objects.exclude(**{field: None})
                .values_list(field, flat=True)
            )
    roles = dict(Profile.objects.values_list('user_id', 'role'))
    taken = set()
    for user in AuthUser.objects.filter(pk__in=refs).order_by('pk'):
        email = (user.email or '').strip().lower() or f'user{user.pk}@third-side.invalid'
        if email in taken:
            email = f'dup{user.pk}.{email}'
        taken.add(email)
        NewUser.objects.create(
            pk=user.pk,
            email=email,
            name=(f'{user.first_name} {user.last_name}').strip(),
            password=user.password,
            last_login=user.last_login,
            is_active=user.is_active,
            role=roles.get(user.pk, 'READER'),
        )


def reset_sequence(apps, schema_editor):
    """Rows were inserted with explicit ids: move the Postgres sequence past them."""
    if schema_editor.connection.vendor != 'postgresql':
        return
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "SELECT setval(pg_get_serial_sequence('third_side_thirdsideuser', 'id'), "
            "COALESCE((SELECT MAX(id) FROM third_side_thirdsideuser), 1))"
        )


